import * as fz from "../converters/fromZigbee";
import * as tz from "../converters/toZigbee";
import * as onesti from "../devices/onesti";
import * as exposes from "../lib/exposes";
import * as reporting from "../lib/reporting";
import type {DefinitionWithExtend, Fz, KeyValueAny} from "../lib/types";

const e = exposes.presets;
const ea = exposes.access;

const fzLocal = {
    easycode_action: {
        cluster: "closuresDoorLock",
        type: "raw",
        convert: (model, msg, publish, options, meta) => {
            const lookup: KeyValueAny = {
                13: "lock",
                14: "zigbee_unlock",
                3: "rfid_unlock",
                0: "keypad_unlock",
            };
            const value = lookup[msg.data[4]];
            if (value === "lock" || value === "zigbee_unlock") {
                return {action: value};
            }
            return {action: lookup[msg.data[3]]};
        },
    } satisfies Fz.Converter<"closuresDoorLock", undefined, "raw">,
};

export const definitions: DefinitionWithExtend[] = [
    {
        zigbeeModel: ["EasyCode903G2.1"],
        model: "EasyCode903G2.1",
        vendor: "EasyAccess",
        description: "EasyFinger V2",
        fromZigbee: [fz.lock, fzLocal.easycode_action, fz.battery],
        toZigbee: [tz.lock, onesti.tzLocal.easycode_auto_relock, tz.lock_sound_volume],
        configure: async (device, coordinatorEndpoint) => {
            const endpoint = device.getEndpoint(11);
            await reporting.bind(endpoint, coordinatorEndpoint, ["closuresDoorLock", "genPowerCfg"]);
            await reporting.lockState(endpoint);
            await reporting.batteryPercentageRemaining(endpoint);
        },
        exposes: [
            e.lock(),
            e.battery(),
            e.sound_volume(),
            e.action(["zigbee_unlock", "lock", "rfid_unlock", "keypad_unlock"]),
            e.binary("auto_relock", ea.STATE_SET, true, false).withDescription("Auto relock after 7 seconds."),
        ],
        whiteLabel: [{vendor: "Datek Wireless", model: "EasyCode903G2.1"}],
    },
];
export const lockUserStatus: KeyValueNumberString = {
    0: "available",
    1: "enabled",
    3: "disabled",
};

export const easyCodeTouchActions: KeyValueNumberString = {
    // First byte are source / msg.data[3]
    // 0x00 KeyPad: If the user uses the code panel.
    // 0x02 Manual: If the user used a key, button or fingerprint.
    // 0x03 RFID: If the user used an RFID tag.
    // 0xFF Other: If the user used an unknown method

    // Last byte are eventCode / msg.data[4]
    // 0x00 Lock: The device was locked using either button, code panel or RFID.
    // 0x01 Unlock: The device was unlocked using either button, code panel or RFID.
    // 0x08 Key Lock: If the user locked with a key.
    // 0x09 Key Unlock: If the user unlocked with a key.
    // 0x10 Fingerprint Lock: The device was locked using fingerprint.
    // 0x11 Fingerprint Unlock: The device was unlocked using fingerprint.

    0: "keypad_lock",
    1: "keypad_unlock",

    // Manual says 0x0001 but the lock sends 0x0002 when you unlock it using the keypad
    2: "keypad_unlock",

    512: "manual_lock",
    513: "manual_unlock",

    520: "key_lock",
    521: "key_unlock",

    528: "fingerprint_lock",
    529: "fingerprint_unlock",

    768: "rfid_lock",
    769: "rfid_unlock",

    65293: "lock",
    65294: "zigbee_unlock",
