/Users/raman/.bashrc: line 2: /private/tmp/claude-501/-Users-raman/a7dfd7d7-c945-450a-b54d-0eac5add44b1/scratchpad/shell-probe.log: No such file or directory
                slot_num, True
            ):
                self._confirm_slot(slot_num, SlotCredential.known(code))
        elif property_name == "userIdStatus" and not isinstance(value, bool):
            if value == CodeSlotStatus.ENABLED:
                self._slot_enabled[slot_num] = True
            elif value == CodeSlotStatus.DISABLED:
                self._slot_enabled[slot_num] = False
            elif value == CodeSlotStatus.AVAILABLE:
                self._slot_enabled[slot_num] = False
                # Ignore AVAILABLE when Lock Code Manager expects a PIN on
                # this slot. Some locks send stale AVAILABLE events after a
                # code was set, which would cause infinite sync loops.
                if self._expects_pin(slot_num):
                    LOGGER.debug(
                        "Lock %s: ignoring userIdStatus=AVAILABLE for slot %s "
                        "(LCM expects PIN on this slot)",
                        self.lock.entity_id,
                        slot_num,
                    )
                else:
                    self._confirm_slot(slot_num, SlotCredential.empty())

    @callback
    def _process_notification(
        self,
        label: str,
        event_label: str,
        payload: bytes | str,
    ) -> None:
        """
        Fire a code slot event for a keypad lock or unlock operation.

        The value is the notification's parsed User Code Report, whose
        ``userId`` is the slot that operated the lock. Raw-buffer parameters
        arrive as a hex string instead and name nobody, so anything that is
        not a dict with a numeric user id is dropped rather than guessed at.

        A duplicate refusal is no use of a code: it marks the write in
        flight refused when it answers that write, and is dropped otherwise.
        """
        if label.lower() != NOTIFICATION_ACCESS_CONTROL:
            return
        value = _unwrap_mqtt_value(payload)
        user_id = value.get("userId") if isinstance(value, dict) else None
        if event_label.lower() == DUPLICATE_CODE_EVENT:
            if refuses_write_in_flight(self._write_slot, parse_slot_num(user_id)):
                self._write_refused = True
            return
        # ``False`` is a valid mapping value (an unlock), so this compares
        # against None -- a truthiness test would drop every unlock event.
        if (to_locked := KEYPAD_EVENT_TO_LOCKED.get(event_label.lower())) is None:
            return
        if (code_slot := parse_slot_num(user_id)) is None:
            LOGGER.debug(
                "Lock %s: ignoring %s notification naming no code slot: %r",
                self.lock.entity_id,
                event_label,
                value,
            )
            return
        # Only the keypad's lock and unlock operations reach here, so the
        # credential is a Personal Identification Number.
        self.async_fire_code_slot_event(
            code_slot=code_slot,
            to_locked=to_locked,
            credential_type=CredentialType.PIN,
        )

            return None

    @callback
    @override
    def teardown_push_subscription(self) -> None:
        """Unsubscribe from credential change events."""
        self._clear_push_unsubs()

    @callback
    def _zwave_js_event_filter(self, event_data: dict[str, Any]) -> bool:
        """Return True if the event belongs to this lock's node."""
        assert self.node.client.driver
        return (
            event_data[ATTR_HOME_ID] == self.node.client.driver.controller.home_id
            and event_data[ATTR_NODE_ID] == self.node.node_id
            and event_data[ATTR_DEVICE_ID] == self.lock.device_id
        )

    @callback
    def _handle_zwave_js_event(self, evt: Event) -> None:
        """Handle Z-Wave JS event."""
        if evt.data[ATTR_TYPE] != NotificationType.ACCESS_CONTROL:
            _LOGGER.debug(
                "Lock %s received non Access Control event: %s",
                self.lock.entity_id,
                evt.as_dict(),
            )
            return

        params = evt.data.get(ATTR_PARAMETERS) or {}
        code_slot = params.get("userId", 0)

        duplicate = (
            AccessControlNotificationEvent.NEW_USER_CODE_NOT_ADDED_DUE_TO_DUPLICATE_CODE
        )
        if evt.data[ATTR_EVENT] == duplicate and refuses_write_in_flight(
            self._uc_write_slot, code_slot
        ):
            self._uc_write_refused = True
            return

        self.async_fire_code_slot_event(
            code_slot=code_slot,
            to_locked=next(
                (
                    to_locked
                    for to_locked, codes in ACCESS_CONTROL_NOTIFICATION_TO_LOCKED.items()
                    if evt.data[ATTR_EVENT] in codes
                ),
                None,
            ),
            credential_type=CredentialType.PIN,
        )

